fast_pseudocode:
# Correct approach: autotune MUST vary tile dimensions to address bank conflicts
@triton.autotune(
    configs=[
        Config({'BLOCK_M': 32, 'BLOCK_N': 32, 'BLOCK_K': 32}, num_warps=2, num_stages=3),
        Config({'BLOCK_M': 64, 'BLOCK_N': 32, 'BLOCK_K': 32}, num_warps=4, num_stages=3),
        Config({'BLOCK_M': 128, 'BLOCK_N': 32, 'BLOCK_K': 32}, num_warps=4, num_stages=3),
    ],
    key=['M', 'N', 'K']
)
@triton.jit
def kernel(..., BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr, BLOCK_K: tl.constexpr):
    # Smaller BLOCK_N reduces bank conflict footprint for stride_bn access
    b = tl.load(B + idx_m + stride_bn*idx_n)

